#!/usr/bin/env python3
"""Source-backed cable review: saved cable STLs over published robot triangles.
No route generation, connector relocation, cable cuts or electrical approval.
Run: python3 tools/build_cable_review.py --cad-root ../../ce-cad --out research/cable-review-2026-09-09
Then node tools/render_cable_review.mjs OUT CAD_ROOT and repeat with --document.
"""
import argparse,base64,csv,hashlib,html,json,re,sys,subprocess
from pathlib import Path

def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--cad-root',type=Path,required=True);ap.add_argument('--out',type=Path,required=True);ap.add_argument('--document',action='store_true');a=ap.parse_args()
 root=Path(__file__).resolve().parents[1];out=a.out.resolve();out.mkdir(parents=True,exist_ok=True);sys.path.insert(0,str(a.cad_root.resolve()))
 from cecad.reviewpack import stl_mesh,viewer
 paths=['wiring/cables.json','ce-assemblies/microduck/current/harness.json','out/wiring/hat-connectors.json','reference/pollen-elec-rpi-robot-hat/elec_RPI_Robot_HAT.kicad_pcb','tools/hat_connectors.py','tools/build_cable_review.py','tools/render_cable_review.mjs','reference/makerworld-3250889/upstream-github-fanhao375-microduck-replica-2549257/README.en.md']
 wire=json.loads((root/paths[0]).read_text())['record'];harness=json.loads((root/paths[1]).read_text())['record'];hat=json.loads((root/paths[2]).read_text())['record']
 source=a.cad_root.resolve()/'out/web/meshes/microduck.json';robot=json.loads(source.read_text());rows=[];cables=[]
 for r in harness['cables']:
  w=next(x for x in wire['cables'] if x['id']==r['id']);f=root/r['geometry'] if r.get('geometry') else None
  rows.append({'id':r['id'],'from':w['from'],'to':w['to'],'pins':w['pins'],'connector':w['connector'],'quantity':w['qty'],'source_route_verdict':r['verdict'],'geometry':r.get('geometry'),'physical_cut_mm':None,'physical_route_verdict':'CANNOT DETERMINE','rendered':bool(f)})
  if f:
   m=stl_mesh(f);m['name']='Cable / '+r['id'];m['color']=[.82,.08,.09] if r['verdict']=='FAIL' else ([.05,.45,.82] if r['id']=='tof-hat' else [1,.42,.04]);cables.append(m);paths.append(r['geometry'])
 context=[dict(x,color=[.70,.75,.78]) for x in robot['parts']]
 uncovered=[x for x in context if not re.search('shell|face-part|eye-ring|soft-mouth',x['name'])]
 def centerz(p): return sum(p['positions'][2::3])/len(p['positions'][2::3])
 scenes={'Whole robot and cables':context+cables,'Inside and cables':uncovered+cables,'Head connections':[x for x in uncovered if centerz(x)>160]+[x for x in cables if min(x['positions'][2::3])>145],'Leg connections':[x for x in uncovered if centerz(x)<155]+[x for x in cables if max(x['positions'][2::3])<165],'Cable routes only':cables}
 scope='Actual published robot triangles + saved candidate cable STLs, zero pose, mm. Orange: unverified route; red: historical route FAIL; blue: ToF candidate. Exact endpoints, cuts, bend and moving clearance remain unverified. 原机器人网格与候选线缆；仅供审查。'
 if not a.document:
  for name,parts in scenes.items():viewer(out/(name+'.html'),{'id':'microduck-cable-review','units':'mm','parts':parts},name,scope,'START HERE.html')
  (out/'Cable overlay.json').write_text(json.dumps({'id':'microduck-cable-review','units':'mm','frame':wire['frame'],'scope':scope,'parts':cables},separators=(',',':')))
  (out/'Connections.json').write_text(json.dumps(rows,indent=2,ensure_ascii=False));
  with (out/'Connections.csv').open('w',newline='',encoding='utf-8-sig') as f:
   writer=csv.DictWriter(f,fieldnames=rows[0]);writer.writeheader();writer.writerows(rows)
  import ast
  tree=ast.parse((root/'tools/hat_connectors.py').read_text());fn=next(x for x in tree.body if isinstance(x,ast.FunctionDef) and x.name=='kicad_footprints');ns={'re':re}
  exec(compile(ast.Module(body=[fn],type_ignores=[]),'hat_connectors.kicad_footprints','exec'),ns)
  pins=ns['kicad_footprints'](str(root/paths[3])); selected={k:pins[k]['nets'] for k in ('J1','J2','J4','J5','J9','J13','J14')}
  for r in hat['connectors']:
   if r['refdes'] in selected and r['nets_by_pin']!=selected[r['refdes']]:raise ValueError('Source pin map drift: '+r['refdes'])
  (out/'Public HAT pin evidence.json').write_text(json.dumps({'source_revision':'23eab11927f95ceca0dfa35bf182caeb7db39ea0','source_sha256':sha(root/paths[3]),'method':'Read footprint pad nets from pinned KiCad PCB, compare existing projected connector record','nets_by_refdes':selected,'installed_identity':'CANNOT DETERMINE'},indent=2))
  (out/'PROVENANCE.json').write_text(json.dumps({'generator':'tools/build_cable_review.py','source_project_commit':subprocess.check_output(['git','-C',str(root),'rev-parse','HEAD'],text=True).strip(),'working_tree_scope':'Current source files are hashed individually; this is not a claim that all files are committed. Freeze the final review from a committed revision.','viewer_template_sha256':sha(a.cad_root.resolve()/'web/review-viewer.html'),'community_reference_revision':'254925717170cca6cd7fcacdbda49db781bad1ae','source_mesh':str(source),'source_mesh_sha256':sha(source),'robot_parts':len(context),'rendered_cables':len(cables),'connections':len(rows),'source_files':[{'path':p,'sha256':sha(root/p)} for p in paths],'excluded_saved_stls':sorted(str(p.relative_to(root)) for p in (root/'out/wiring/cad').glob('*.stl') if str(p.relative_to(root)) not in paths),'scope':scope,'physical_simulation':'CANNOT DETERMINE: saved routing candidates are not flexible-cable mechanics'},indent=2))
  return
 def picture(name,caption):
  p=out/(name+'.png');return '<figure><a href="'+name+'.html"><img alt="'+name+'" src="data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()+'"></a><figcaption>'+caption+' <a href="'+name+'.html">Turn this view / 旋转查看</a></figcaption></figure>'
 content='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Microduck — cables and connections</title><style>body{font:17px/1.6 system-ui;color:#183346;background:#edf2f5;margin:0}main{max-width:1160px;margin:auto;padding:38px}h1{font-size:40px}h2{margin-top:40px}figure,.card{margin:20px 0;background:white;padding:22px;border-radius:14px}img{width:100%;height:auto}figcaption{font-size:16px}table{border-collapse:collapse;width:100%;background:white;font-size:14px}td,th{text-align:left;padding:12px;border:1px solid #d6e0e5;vertical-align:top}.gate{border-left:6px solid #c94538;padding:18px;background:#fff3ef}a{color:#006986}small{color:#4f6470}@media print{body{background:white}main{padding:0}figure,.card,tr{break-inside:avoid}h2{break-after:avoid}}</style><main><h1>Microduck<br>Cables & connections / 线缆与连接</h1><p>Review the wiring inside our current robot. The pictures use the actual published robot meshes and 16 saved cable models. Click a picture to rotate it offline in Edge or Chrome.</p><p>查看当前机器人内部接线。图片采用实际已发布机器人网格和16根候选线缆模型。点击图片可在浏览器中离线旋转。</p><div class="gate"><b>Review stage — do not power the robot from this guide yet.<br>审查阶段：本指南暂不能用于通电操作。</b><p>The current design still uses 15 ROBOTIS Dynamixel XL330-M288-T servos. No cheap-servo substitution has been approved. The public HAT connects servo power to battery voltage; XL330 is rated 3.7–6.0 V. The modeled 2S supply exceeds that rating. The power stage and actual board revision must be resolved first. The public HAT audit also records 40 DRC errors and 9 warnings. <a href="JLC PCB files.html">PCB quotation file map / PCB报价文件核对</a>.</p><p>当前仍使用15个原规格XL330舵机，尚未采用廉价替代。公开HAT舵机供电连接电池，而XL330额定电压为3.7–6.0 V；当前2S电源模型超出额定值，必须先解决供电与板卡版本问题；公开HAT检查还记录40项DRC错误和9项警告。</p></div>'''
 content+=picture('Whole robot and cables','Grey: real robot geometry. Orange: unverified candidate routes. Red: routes with a recorded failure. Blue: distance sensor lead. 灰色为机器人；橙色为待验证线缆，红色为已有失败记录，蓝色为测距传感器线。')
 content+='<h2>1. Open the covers / 先打开外壳</h2><p>Identify the battery in the body, the computer and HAT in the head, and the numbered servo chain. Keep the battery disconnected while checking connector identity and alignment. 图中显示电池、头部计算机与HAT，以及舵机链。确认接头和方向时保持电池断开。</p>'+picture('Inside and cables','Covers removed from actual geometry. Cable diameter is a historical nominal model value, not a measured jacket diameter. 隐藏实际外壳网格；线径为候选值，尚未经实物测量。')
 content+='''<h2>2. Follow the servo chain / 核对舵机链</h2><div class="card"><b>Head / 头部</b><p>HAT → ID34 → ID33 → ID32 → ID31 → ID30 → IMU ID200</p><b>Left leg / 左腿</b><p>IMU ID200 → ID20 → ID21 → ID22 → ID23 → ID24</p><b>Right leg / 右腿</b><p>IMU ID200 → ID10 → ID11 → ID12 → ID13 → ID14</p><p>This is the existing proposed cable topology, not a proven factory harness. The IMU junction board and its socket allocation remain unconfirmed. The ID33–ID32 connection has no successful saved route. 上述为现有候选连接拓扑，并非已验证原厂线束；IMU接头分配未确认，ID33至ID32尚无成功路由。</p><p><b>XL330 cable pin numbers:</b> 1 GND · 2 VDD · 3 DATA. JST EH 3-pin, EHR-03 housing. Use connector pin numbers; a plug viewed from its wire side is mirrored relative to its mating side. This page does not assign a left-to-right orientation from an unknown photograph. 舵机线：1地、2电源、3数据；按接头编号检查，不凭照片左右顺序判断。</p></div>'''
 content+=picture('Head connections','Head and neck: inspect the routes at the moving joints. The cable model does not prove slack or moving clearance. 头颈运动关节需进一步验证余量与动态间隙。')+picture('Leg connections','Legs: inspect the visible bends before closing the covers. No cable cut length is approved. 双腿弯折处需要检查，目前没有批准的裁线长度。')
 content+='''<h2>3. Connect the head electronics / 核对头部电子连接</h2><table><tr><th>Connection / 连接</th><th>Public source says / 公开资料</th><th>Still to verify / 仍需确认</th></tr><tr><td>HAT ↔ Radxa Zero 3W</td><td>2×20 header; power pins 2/4 = 5 V. UART pins 8/10; I²C pins 3/5. Board-to-board connection, no cable.</td><td>Match pin 1 and all 40 pins with the actual board drawing. Do not rotate the board solely because screw holes align. 对照实际板卡确认1号针及40针位置。</td></tr><tr><td>ToF distance sensor / 测距传感器</td><td>Public HAT J5: pin 1 GND, 2 +3V3, 3 SDA, 4 SCL; JST SH 4-pin.</td><td>Exact sensor model, sensor-end connector and cable orientation unknown. 传感器型号、另一端接头及方向未确认。</td></tr><tr><td>Speaker / 扬声器</td><td>Public HAT J1 is the differential speaker output via amplifier/filter, Wago terminal footprint.</td><td>Original speaker impedance, termination and polarity labeling need confirmation. Neither speaker terminal is a ground return. 阻抗与端接未确认，两个输出端均不应当作地线。</td></tr><tr><td>Camera / 摄像头</td><td>Radxa side uses a 22-pin 0.5 mm CSI ribbon connector.</td><td>Camera identity, opposite-end pin count, contacts-facing direction and adapter unknown. No ribbon polarity guessed. 摄像头端针数、触点方向及转接线未确认。</td></tr><tr><td>Microphone / 麦克风</td><td>Public HAT already has an onboard microphone; J2/J9 are optional external paths.</td><td>External microphone is not automatically required. Confirm actual board first. 先确认实物板，不能默认需要外置麦克风。</td></tr><tr><td>Battery / 电池</td><td>NP-F550 contact arrangement through a contact board is modeled.</td><td>Contact hardware, polarity, protection and servo regulator are unresolved. Do not wire raw 2S directly to XL330 under this guide. 电池触点、保护与舵机稳压尚未解决。</td></tr></table>'''
 content+='''<h2>4. Before closing or powering / 合壳和通电前</h2><ol><li>Confirm the exact HAT, IMU, camera and ToF board revisions against their drawings. 确认各板卡实际版本。</li><li>Verify each connector pin number, voltage and polarity with the matching source drawing; label both cable ends. 按对应图纸核对针脚、电压、极性，并标记线缆两端。</li><li>Resolve the servo voltage mismatch before connecting the battery. 先解决舵机供电超压问题。</li><li>With power disconnected, check slack and pinching through the intended joint range; retain loops and strain relief only after clearance is measured. 断电检查全行程余量、夹线和固定位置。</li><li>Measure the actual routed lengths, then finalize cable cuts. The current pictures do not provide cut lengths. 实际走线测量后才能确定裁线长度。</li></ol>'''
 content+=picture('Cable routes only','These are the 16 saved candidate cable solids, with no new routes invented for missing wires. 本图为16根已保存候选线缆，没有虚构缺失线缆。')
 content+='<h2>Every connection / 全部连接</h2><p>All 23 records are shown, including one descriptive port row with quantity zero and the direct board header. Download <a href="Connections.csv">the connection list / 连接清单</a>.</p><table><tr><th>Cable</th><th>From → To</th><th>Saved route</th><th>Physical length</th></tr>'
 for r in rows:content+='<tr><td>'+html.escape(r['id'])+'</td><td>'+html.escape(r['from']+' → '+r['to'])+'</td><td>'+('Rendered candidate / 已显示候选' if r['rendered'] else 'No routed cable model / 无路由模型')+'<br>'+html.escape(r['source_route_verdict'])+'</td><td>Not established / 未确定</td></tr>'
 content+='''</table><h2>Where this comes from / 来源与版本</h2><p>Our robot geometry and saved cable routes are recorded by SHA-256 in <a href="PROVENANCE.json">PROVENANCE.json</a>. The public HAT is pinned to revision <code>23eab11927f95ceca0dfa35bf182caeb7db39ea0</code>; <a href="Public HAT pin evidence.json">pin evidence</a> is read back from its KiCad PCB. The HAT mesh and released board differ: a historical J14 projection differs by 49.75 mm. The images retain this discrepancy for review rather than presenting it as an approved connection.</p><p><a href="https://github.com/fanhao375/microduck-replica/tree/254925717170cca6cd7fcacdbda49db781bad1ae">fanhao375/microduck-replica at 2549257</a> documents printed structural parts and screws fitting the leg parts. Its README explicitly says the remaining work is analysis; this is not evidence of a complete working replica. That repository is Git-versioned. Our review records are separately preserved, with exact source hashes. The original robot's software, public board designs and simulation meshes have different release/licensing scopes.</p><p>参考项目公开记录了结构件打印和腿部螺钉试装，不等于整机已完成验证。上游采用Git版本管理，本次审查另保存来源哈希。实物板版本、柔性线缆运动及生产就绪程度仍未验证。</p></main></html>'''
 (out/'START HERE.html').write_text(content)
if __name__=='__main__':main()
